#!/bin/bash
ENV="$1"
case "$ENV" in
  prod|production) echo "Deploying to PRODUCTION"; REPLICAS=5;;
  staging)         echo "Deploying to STAGING"; REPLICAS=2;;
  dev|local)       echo "Deploying to DEV"; REPLICAS=1;;
  *)               echo "Unknown env: $ENV. Use prod|staging|dev"; exit 1;;
esac
echo "Replicas: $REPLICAS"

file="/home/user/report.txt"
echo "${file##*/}"        # report.txt  (basename)
echo "${file%.*}"         # /home/user/report  (strip ext)
echo "${file/user/admin}" # /home/admin/report.txt

str="Hello World"
echo "${#str}"            # 11  (length)
echo "${str,,}"           # hello world  (lowercase)
echo "${str^^}"           # HELLO WORLD  (uppercase)
